140	mod tests {
141	    use tempfile::tempdir;
142	    use tokio::fs;
143	
144	    use super::*;
145	
146	    #[test]
147	    fn test_known_channels_includes_all_four() {
148	        let names = bundled_channel_names();
149	        assert!(names.contains(&"telegram"));
150	        assert!(names.contains(&"slack"));
151	        assert!(names.contains(&"discord"));
152	        assert!(names.contains(&"whatsapp"));
153	        assert!(names.contains(&"xmpp"));
154	    }
155	
156	    #[test]
157	    fn test_channels_src_dir_default() {
158	        let dir = channels_src_dir();
159	        assert!(dir.ends_with("channels-src"));
160	    }
161	
162	    #[test]
163	    fn test_locate_unknown_channel_errors() {
164	        assert!(locate_channel_artifacts("nonexistent").is_err());
165	    }
166	
167	    #[tokio::test]
168	    async fn test_install_refuses_overwrite_without_force() {
169	        let dir = tempdir().unwrap();
170	        let wasm_path = dir.path().join("telegram.wasm");
171	        fs::write(&wasm_path, b"custom").await.unwrap();
172	
173	        let result = install_bundled_channel("telegram", dir.path(), false).await;
174	        // Either fails because artifacts missing OR because file exists
175	        assert!(result.is_err());
176	
177	        // Original file should be untouched
178	        let existing = fs::read(&wasm_path).await.unwrap();
179	        assert_eq!(existing, b"custom");
180	    }
181	}
