1	//! Serde structs for extension registry manifests.
2	//!
3	//! Each manifest describes a single extension (tool or channel) with its source
4	//! location, build artifacts, authentication requirements, and tags.
5	
6	use serde::{Deserialize, Serialize};
7	
8	use crate::extensions::{AuthHint, ExtensionKind, ExtensionSource, RegistryEntry};
9	
10	/// A single extension manifest loaded from `registry/{tools,channels,mcp-servers}/<name>.json`.
11	#[derive(Debug, Clone, Serialize, Deserialize)]
12	pub struct ExtensionManifest {
13	    /// Unique identifier (matches crate name stem, e.g. "slack").
14	    pub name: String,
15	
16	    /// Human-readable name (e.g. "Slack").
17	    pub display_name: String,
18	
19	    /// Whether this is a tool, channel, or MCP server.
20	    pub kind: ManifestKind,
21	
22	    /// Semver version from Cargo.toml. Optional for MCP server manifests.
23	    #[serde(default)]
24	    pub version: Option<String>,
25	
26	    /// One-line description.
27	    pub description: String,
28	
29	    /// Search keywords beyond the name.
30	    #[serde(default)]
31	    pub keywords: Vec<String>,
32	
33	    /// Source code location and build info. Absent for MCP server manifests.
34	    #[serde(default)]
35	    pub source: Option<SourceSpec>,
36	
37	    /// Pre-built binary artifacts keyed by target triple.
38	    #[serde(default)]
39	    pub artifacts: std::collections::HashMap<String, ArtifactSpec>,
40	
41	    /// Summary of authentication requirements.
42	    #[serde(default)]
43	    pub auth_summary: Option<AuthSummary>,
44	
45	    /// Tags for filtering (e.g. "default", "messaging", "google").
46	    #[serde(default)]
47	    pub tags: Vec<String>,
48	
49	    /// MCP server URL. Only present for `McpServer` manifests.
50	    #[serde(default)]
51	    pub url: Option<String>,
52	
53	    /// MCP auth method: "dcr", "oauth_pre_configured:<setup_url>", or "none".
54	    /// Only present for `McpServer` manifests.
55	    #[serde(default)]
56	    pub auth: Option<String>,
57	}
58	
59	/// Extension kind as declared in manifests.
60	#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
61	#[serde(rename_all = "snake_case")]
62	pub enum ManifestKind {
63	    Tool,
64	    Channel,
65	    McpServer,
66	}
67	
68	impl From<ManifestKind> for ExtensionKind {
69	    fn from(kind: ManifestKind) -> Self {
70	        match kind {
71	            ManifestKind::Tool => ExtensionKind::WasmTool,
72	            ManifestKind::Channel => ExtensionKind::WasmChannel,
73	            ManifestKind::McpServer => ExtensionKind::McpServer,
74	        }
75	    }
76	}
77	
78	impl std::fmt::Display for ManifestKind {
79	    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
80	        match self {
81	            ManifestKind::Tool => write!(f, "tool"),
82	            ManifestKind::Channel => write!(f, "channel"),
83	            ManifestKind::McpServer => write!(f, "mcp_server"),
84	        }
85	    }
86	}
87	
88	/// Source code location for building from source.
89	#[derive(Debug, Clone, Serialize, Deserialize)]
90	pub struct SourceSpec {
91	    /// Path relative to repo root (e.g. "tools-src/slack").
92	    pub dir: String,
93	
94	    /// Capabilities filename relative to source dir.
95	    pub capabilities: String,
96	
97	    /// Rust crate name for `cargo component build`.
98	    pub crate_name: String,
99	}
100	
101	/// A pre-built binary artifact.
102	#[derive(Debug, Clone, Serialize, Deserialize)]
103	pub struct ArtifactSpec {
104	    /// Download URL (null until release).
105	    /// Can point to a `.wasm` file or a `.tar.gz` bundle containing both
106	    /// `{name}.wasm` and `{name}.capabilities.json`.
107	    pub url: Option<String>,
108	
109	    /// Hex SHA256 of the downloaded artifact (null until release).
110	    pub sha256: Option<String>,
111	
112	    /// Optional separate download URL for the capabilities file.
113	    /// Only needed when `url` points to a bare `.wasm` file instead of a bundle.
114	    #[serde(default, skip_serializing_if = "Option::is_none")]
115	    pub capabilities_url: Option<String>,
116	}
117	
118	/// Summary of authentication requirements extracted from capabilities.
119	#[derive(Debug, Clone, Serialize, Deserialize)]
120	pub struct AuthSummary {
121	    /// Auth method: "oauth", "manual", or "none".
122	    #[serde(default)]
123	    pub method: Option<String>,
124	
125	    /// Display name for the auth provider (e.g. "Google", "Slack").
126	    #[serde(default)]
127	    pub provider: Option<String>,
128	
129	    /// Secret names required by this extension.
130	    #[serde(default)]
131	    pub secrets: Vec<String>,
132	
133	    /// If this extension shares auth with others (e.g. all Google tools share
134	    /// `google_oauth_token`), this is the shared secret name.
135	    #[serde(default)]
136	    pub shared_auth: Option<String>,
137	
138	    /// URL where users can set up credentials.
139	    #[serde(default)]
140	    pub setup_url: Option<String>,
141	}
142	
143	/// Bundle definition grouping related extensions.
144	#[derive(Debug, Clone, Serialize, Deserialize)]
145	pub struct BundleDefinition {
146	    /// Human-readable name.
147	    pub display_name: String,
148	
149	    /// Description of what this bundle contains.
150	    #[serde(default)]
151	    pub description: Option<String>,
152	
153	    /// Extension references as "tools/<name>" or "channels/<name>".
154	    pub extensions: Vec<String>,
155	
156	    /// Shared auth secret across bundle members (if any).
157	    #[serde(default)]
158	    pub shared_auth: Option<String>,
159	}
160	
161	/// Top-level structure of `_bundles.json`.
162	#[derive(Debug, Clone, Default, Serialize, Deserialize)]
163	pub struct BundlesFile {
164	    pub bundles: std::collections::HashMap<String, BundleDefinition>,
165	}
166	
167	impl ExtensionManifest {
168	    /// Convert this manifest into a [`RegistryEntry`] for use with the in-chat
169	    /// extension discovery system.
170	    ///
171	    /// Returns `None` for MCP server manifests missing a `url` field.
172	    pub fn to_registry_entry(&self) -> Option<RegistryEntry> {
173	        if self.kind == ManifestKind::McpServer {
174	            return self.to_mcp_registry_entry();
175	        }
176	
177	        Some(self.to_wasm_registry_entry())
178	    }
179	
180	    /// Build a [`RegistryEntry`] for an MCP server manifest.
181	    fn to_mcp_registry_entry(&self) -> Option<RegistryEntry> {
182	        let url = match &self.url {
183	            Some(u) => u.clone(),
184	            None => {
185	                tracing::warn!(
186	                    "MCP server manifest '{}' is missing 'url' field, skipping",
187	                    self.name
188	                );
189	                return None;
190	            }
191	        };
192	        let auth_hint = match self.auth.as_deref() {
193	            Some("dcr") | None => AuthHint::Dcr,
194	            Some("none") => AuthHint::None,
195	            Some(other) if other.starts_with("oauth_pre_configured:") => {
196	                AuthHint::OAuthPreConfigured {
197	                    setup_url: other
198	                        .strip_prefix("oauth_pre_configured:")
199	                        .unwrap_or("")
200	                        .to_string(),
201	                }
202	            }
203	            _ => AuthHint::Dcr,
204	        };
205	
206	        Some(RegistryEntry {
207	            name: self.name.clone(),
208	            display_name: self.display_name.clone(),
209	            kind: ExtensionKind::McpServer,
210	            description: self.description.clone(),
211	            keywords: self.keywords.clone(),
212	            source: ExtensionSource::McpUrl { url },
213	            fallback_source: None,
214	            auth_hint,
215	            version: self.version.clone(),
216	        })
217	    }
218	
219	    /// Build a [`RegistryEntry`] for a WASM tool or channel manifest.
220	    fn to_wasm_registry_entry(&self) -> RegistryEntry {
221	        let source_spec = self.source.as_ref();
222	
223	        let buildable = source_spec.map(|s| ExtensionSource::WasmBuildable {
224	            source_dir: s.dir.clone(),
225	            build_dir: Some(s.dir.clone()),
226	            crate_name: Some(s.crate_name.clone()),
227	        });
228	
229	        // Prefer pre-built artifact download when a URL is available,
230	        // with build-from-source as fallback in case the download fails (e.g., 404).
231	        let (source, fallback_source) = if let Some(artifact) = self.artifacts.get("wasm32-wasip2")
232	        {
233	            if let Some(ref url) = artifact.url {
234	                (
235	                    ExtensionSource::WasmDownload {
236	                        wasm_url: url.clone(),
237	                        capabilities_url: artifact.capabilities_url.clone(),
238	                    },
239	                    buildable.map(Box::new),
240	                )
241	            } else if let Some(b) = buildable {
242	                (b, None)
243	            } else {
244	                // No source spec and no download URL — use a placeholder
245	                (
246	                    ExtensionSource::WasmBuildable {
247	                        source_dir: String::new(),
248	                        build_dir: None,
249	                        crate_name: None,
250	                    },
251	                    None,
252	                )
253	            }
254	        } else if let Some(b) = buildable {
255	            (b, None)
256	        } else {
257	            (
258	                ExtensionSource::WasmBuildable {
259	                    source_dir: String::new(),
260	                    build_dir: None,
261	                    crate_name: None,
262	                },
263	                None,
264	            )
265	        };
266	
267	        let auth_hint = match self.auth_summary.as_ref().and_then(|a| a.method.as_deref()) {
268	            Some("oauth") => AuthHint::CapabilitiesAuth,
269	            Some("manual") => AuthHint::CapabilitiesAuth,
270	            Some("none") | None => AuthHint::None,
271	            Some(_) => AuthHint::CapabilitiesAuth,
272	        };
273	
274	        RegistryEntry {
275	            name: self.name.clone(),
276	            display_name: self.display_name.clone(),
277	            kind: self.kind.into(),
278	            description: self.description.clone(),
279	            keywords: self.keywords.clone(),
280	            source,
281	            fallback_source,
282	            auth_hint,
283	            version: self.version.clone(),
284	        }
285	    }
286	}
