292	    #[test]
293	    fn test_parse_tool_manifest() {
294	        let json = r#"{
295	            "name": "slack",
296	            "display_name": "Slack",
297	            "kind": "tool",
298	            "version": "0.1.0",
299	            "description": "Post messages via Slack API",
300	            "keywords": ["messaging"],
301	            "source": {
302	                "dir": "tools-src/slack",
303	                "capabilities": "slack-tool.capabilities.json",
304	                "crate_name": "slack-tool"
305	            },
306	            "artifacts": {
307	                "wasm32-wasip2": { "url": null, "sha256": null }
308	            },
309	            "auth_summary": {
310	                "method": "oauth",
311	                "provider": "Slack",
312	                "secrets": ["slack_bot_token"],
313	                "shared_auth": null,
314	                "setup_url": "https://api.slack.com/apps"
315	            },
316	            "tags": ["default", "messaging"]
317	        }"#;
318	
319	        let manifest: ExtensionManifest = serde_json::from_str(json).expect("parse manifest");
320	        assert_eq!(manifest.name, "slack");
321	        assert_eq!(manifest.kind, ManifestKind::Tool);
322	        assert_eq!(manifest.version.as_deref(), Some("0.1.0"));
323	        assert!(manifest.tags.contains(&"default".to_string()));
324	
325	        let entry = manifest.to_registry_entry().unwrap();
326	        assert_eq!(entry.kind, ExtensionKind::WasmTool);
327	    }
