387	    /// When a manifest has a download URL in artifacts, to_registry_entry()
388	    /// should set WasmDownload as primary source and WasmBuildable as fallback.
389	    #[test]
390	    fn test_manifest_with_download_url_has_buildable_fallback() {
391	        let json = r#"{
392	            "name": "gmail",
393	            "display_name": "Gmail",
394	            "kind": "tool",
395	            "version": "0.1.0",
396	            "description": "Gmail tool",
397	            "keywords": ["email"],
398	            "source": {
399	                "dir": "tools-src/gmail",
400	                "capabilities": "gmail-tool.capabilities.json",
401	                "crate_name": "gmail-tool"
402	            },
403	            "artifacts": {
404	                "wasm32-wasip2": {
405	                    "url": "https://github.com/nearai/ironclaw/releases/latest/download/gmail-wasm32-wasip2.tar.gz",
406	                    "sha256": null
407	                }
408	            },
409	            "tags": ["default"]
410	        }"#;
411	
412	        let manifest: ExtensionManifest = serde_json::from_str(json).expect("parse manifest");
413	        let entry = manifest.to_registry_entry().unwrap();
414	
415	        // Primary source should be WasmDownload
416	        assert!(
417	            matches!(&entry.source, ExtensionSource::WasmDownload { .. }),
418	            "Primary source should be WasmDownload, got {:?}",
419	            entry.source
420	        );
421	
422	        // Fallback should be WasmBuildable with the source dir info
423	        let fallback = entry
424	            .fallback_source
425	            .as_ref()
426	            .expect("Should have fallback_source when download URL is set");
427	        match fallback.as_ref() {
428	            ExtensionSource::WasmBuildable {
429	                build_dir,
430	                crate_name,
431	                ..
432	            } => {
433	                assert_eq!(build_dir.as_deref(), Some("tools-src/gmail"));
434	                assert_eq!(crate_name.as_deref(), Some("gmail-tool"));
435	            }
436	            other => panic!("Fallback should be WasmBuildable, got {:?}", other),
437	        }
438	    }
