12	// GitHub-only by design. New trusted hosts (e.g. a NEAR AI CDN) must be
13	// explicitly added here; unknown hosts fall back to source build with a
14	// warning rather than surfacing a clear "host not allowed" error.
15	const ALLOWED_ARTIFACT_HOSTS: &[&str] = &[
16	    "github.com",
17	    "objects.githubusercontent.com",
18	    "github-releases.githubusercontent.com",
19	    "raw.githubusercontent.com",
20	];
21	
22	fn should_attempt_source_fallback(err: &RegistryError) -> bool {
23	    match err {
24	        // `releases/latest` is a moving target: every new release rebuilds WASM
25	        // extensions, so a mismatch against a `latest` URL just means the binary
26	        // was compiled against an older release's checksum. Not a security concern
27	        // — fall back to building from source.
28	        //
29	        // Version-pinned URLs (`releases/download/vX.Y.Z/`) point to an immutable
30	        // asset; a mismatch there is genuinely suspicious and remains a hard block.
31	        RegistryError::ChecksumMismatch { url, .. } => {
32	            url.contains("github.com/nearai/ironclaw/releases/latest/")
33	        }
34	        // Never fall back for these — they signal a structural problem or a
35	        // deliberate "already done" state, not a transient artifact issue.
36	        RegistryError::AlreadyInstalled { .. } | RegistryError::InvalidManifest { .. } => false,
37	        _ => true,
38	    }
39	}
40	
41	fn is_allowed_artifact_host(host: &str) -> bool {
42	    ALLOWED_ARTIFACT_HOSTS
43	        .iter()
44	        .any(|allowed| host.eq_ignore_ascii_case(allowed))
45	        || host.ends_with(".githubusercontent.com")
46	}
47	
48	fn validate_artifact_url(
49	    manifest_name: &str,
50	    field: &'static str,
51	    url: &str,
52	) -> Result<(), RegistryError> {
53	    let parsed = reqwest::Url::parse(url).map_err(|e| RegistryError::InvalidManifest {
54	        name: manifest_name.to_string(),
55	        field,
56	        reason: format!("invalid URL: {}", e),
57	    })?;
58	
59	    if parsed.scheme() != "https" {
60	        return Err(RegistryError::InvalidManifest {
61	            name: manifest_name.to_string(),
62	            field,
63	            reason: "URL must use https".to_string(),
64	        });
65	    }
66	
67	    let host = parsed
68	        .host_str()
69	        .ok_or_else(|| RegistryError::InvalidManifest {
70	            name: manifest_name.to_string(),
71	            field,
72	            reason: "URL host is missing".to_string(),
73	        })?;
74	
75	    if host.parse::<IpAddr>().is_ok() || !is_allowed_artifact_host(host) {
76	        return Err(RegistryError::InvalidManifest {
77	            name: manifest_name.to_string(),
78	            field,
79	            reason: format!("host '{}' is not allowed", host),
80	        });
81	    }
82	
83	    Ok(())
84	}
85	
86	fn validate_manifest_install_inputs(manifest: &ExtensionManifest) -> Result<(), RegistryError> {
87	    let is_valid_name = !manifest.name.is_empty()
88	        && manifest
89	            .name
90	            .chars()
91	            .all(|c| c.is_ascii_lowercase() || c.is_ascii_digit() || c == '-' || c == '_');
92	
93	    if !is_valid_name {
94	        return Err(RegistryError::InvalidManifest {
95	            name: manifest.name.clone(),
96	            field: "name",
97	            reason: "name must contain only lowercase letters, digits, '-' or '_'".to_string(),
98	        });
99	    }
100	
101	    // MCP servers are not installed via this path
102	    if manifest.kind == ManifestKind::McpServer {
103	        return Ok(());
104	    }
105	
106	    let source = match &manifest.source {
107	        Some(s) => s,
108	        None => {
109	            return Err(RegistryError::InvalidManifest {
110	                name: manifest.name.clone(),
111	                field: "source",
112	                reason: "WASM extensions must have a source spec".to_string(),
113	            });
114	        }
115	    };
116	
117	    let expected_prefix = match manifest.kind {
118	        ManifestKind::Tool => "tools-src/",
119	        ManifestKind::Channel => "channels-src/",
120	        ManifestKind::McpServer => unreachable!(),
121	    };
122	
123	    if !source.dir.starts_with(expected_prefix) {
124	        return Err(RegistryError::InvalidManifest {
125	            name: manifest.name.clone(),
126	            field: "source.dir",
127	            reason: format!("must start with '{}'", expected_prefix),
128	        });
129	    }
130	
131	    let source_path = Path::new(&source.dir);
132	    let has_unsafe_component = source_path.components().any(|component| {
133	        matches!(
134	            component,
135	            Component::ParentDir | Component::RootDir | Component::Prefix(_) | Component::CurDir
136	        )
137	    });
138	
139	    if source_path.is_absolute() || has_unsafe_component {
140	        return Err(RegistryError::InvalidManifest {
141	            name: manifest.name.clone(),
142	            field: "source.dir",
143	            reason: "must be a safe relative path without traversal segments".to_string(),
144	        });
145	    }
146	
147	    let has_path_separator = source.capabilities.contains('/')
148	        || source.capabilities.contains('\\')
149	        || source.capabilities.contains("..");
150	
151	    if has_path_separator {
152	        return Err(RegistryError::InvalidManifest {
153	            name: manifest.name.clone(),
154	            field: "source.capabilities",
155	            reason: "must be a file name without path separators".to_string(),
156	        });
157	    }
158	
159	    Ok(())
160	}
