162	/// Extract the source spec from a manifest, returning an error if absent.
163	fn require_source(manifest: &ExtensionManifest) -> Result<&SourceSpec, RegistryError> {
164	    manifest
165	        .source
166	        .as_ref()
167	        .ok_or_else(|| RegistryError::InvalidManifest {
168	            name: manifest.name.clone(),
169	            field: "source",
170	            reason: "WASM extensions must have a source spec".to_string(),
171	        })
172	}
173	
174	fn download_failure_reason(error: &reqwest::Error) -> String {
175	    if error.is_timeout() {
176	        "request timed out".to_string()
177	    } else if error.is_connect() {
178	        "connection failed".to_string()
179	    } else if error.is_request() {
180	        "request failed".to_string()
181	    } else {
182	        "network error".to_string()
183	    }
184	}
