230	    /// Install a single extension by building from source.
231	    pub async fn install_from_source(
232	        &self,
233	        manifest: &ExtensionManifest,
234	        force: bool,
235	    ) -> Result<InstallOutcome, RegistryError> {
236	        validate_manifest_install_inputs(manifest)?;
237	
238	        if manifest.kind == ManifestKind::McpServer {
239	            return Err(RegistryError::InvalidManifest {
240	                name: manifest.name.clone(),
241	                field: "kind",
242	                reason: "MCP servers cannot be installed from source".to_string(),
243	            });
244	        }
245	
246	        let source = require_source(manifest)?;
247	
248	        let source_dir = self.repo_root.join(&source.dir);
249	        if !source_dir.exists() {
250	            return Err(RegistryError::ManifestRead {
251	                path: source_dir.clone(),
252	                reason: "source directory does not exist".to_string(),
253	            });
254	        }
255	
256	        let target_dir = match manifest.kind {
257	            ManifestKind::Tool => &self.tools_dir,
258	            ManifestKind::Channel => &self.channels_dir,
259	            ManifestKind::McpServer => unreachable!(),
260	        };
261	
262	        fs::create_dir_all(target_dir)
263	            .await
264	            .map_err(RegistryError::Io)?;
265	
266	        // Use manifest.name for installed filenames so discovery, auth, and
267	        // CLI commands (`ironclaw tool auth <name>`) all agree on the stem.
268	        let target_wasm = target_dir.join(format!("{}.wasm", manifest.name));
269	
270	        // Check if already exists
271	        if target_wasm.exists() && !force {
272	            return Err(RegistryError::AlreadyInstalled {
273	                name: manifest.name.clone(),
274	                path: target_wasm,
275	            });
276	        }
277	
278	        // Build the WASM component
279	        println!(
280	            "Building {} '{}' from {}...",
281	            manifest.kind,
282	            manifest.display_name,
283	            source_dir.display()
284	        );
285	        let crate_name = &source.crate_name;
286	        let wasm_path =
287	            crate::registry::artifacts::build_wasm_component(&source_dir, crate_name, true)
288	                .await
289	                .map_err(|e| RegistryError::ManifestRead {
290	                    path: source_dir.clone(),
291	                    reason: format!("build failed: {}", e),
292	                })?;
293	
294	        // Copy WASM binary
295	        println!("  Installing to {}", target_wasm.display());
296	        fs::copy(&wasm_path, &target_wasm)
297	            .await
298	            .map_err(RegistryError::Io)?;
299	
300	        // Copy capabilities file
301	        let caps_source = source_dir.join(&source.capabilities);
302	        let target_caps = target_dir.join(format!("{}.capabilities.json", manifest.name));
303	        let has_capabilities = if caps_source.exists() {
304	            fs::copy(&caps_source, &target_caps)
305	                .await
306	                .map_err(RegistryError::Io)?;
307	            true
308	        } else {
309	            false
310	        };
311	
312	        let mut warnings = Vec::new();
313	        if !has_capabilities {
314	            warnings.push(format!(
315	                "No capabilities file found at {}",
316	                caps_source.display()
317	            ));
318	        }
319	
320	        Ok(InstallOutcome {
321	            name: manifest.name.clone(),
322	            kind: manifest.kind,
323	            wasm_path: target_wasm,
324	            has_capabilities,
325	            warnings,
326	        })
327	    }
328	
329	    pub async fn install_with_source_fallback(
330	        &self,
331	        manifest: &ExtensionManifest,
332	        force: bool,
333	    ) -> Result<InstallOutcome, RegistryError> {
334	        // Validate upfront so we fail fast on bad manifests regardless of
335	        // which install path runs, without relying on inner methods to
336	        // catch it first.
337	        validate_manifest_install_inputs(manifest)?;
338	
339	        if manifest.kind == ManifestKind::McpServer {
340	            return Err(RegistryError::InvalidManifest {
341	                name: manifest.name.clone(),
342	                field: "kind",
343	                reason: "MCP servers cannot be installed via the WASM installer".to_string(),
344	            });
345	        }
346	
347	        let source = require_source(manifest)?;
348	
349	        let has_artifact = manifest
350	            .artifacts
351	            .get("wasm32-wasip2")
352	            .and_then(|a| a.url.as_ref())
353	            .is_some();
354	
355	        if !has_artifact {
356	            return self.install_from_source(manifest, force).await;
357	        }
358	
359	        let source_dir = self.repo_root.join(&source.dir);
360	
361	        match self.install_from_artifact(manifest, force).await {
362	            Ok(outcome) => Ok(outcome),
363	            Err(artifact_err) => {
364	                if !should_attempt_source_fallback(&artifact_err) {
365	                    return Err(artifact_err);
366	                }
367	
368	                if !source_dir.is_dir() {
369	                    return Err(RegistryError::SourceFallbackUnavailable {
370	                        name: manifest.name.clone(),
371	                        source_dir,
372	                        artifact_error: Box::new(artifact_err),
373	                    });
374	                }
375	
376	                tracing::warn!(
377	                    extension = %manifest.name,
378	                    error = %artifact_err,
379	                    "Artifact install failed; falling back to build-from-source"
380	                );
381	
382	                match self.install_from_source(manifest, force).await {
383	                    Ok(mut outcome) => {
384	                        outcome.warnings.push(format!(
385	                            "Artifact install failed ({}); installed via source fallback.",
386	                            artifact_err
387	                        ));
388	                        Ok(outcome)
389	                    }
390	                    Err(source_err) => Err(RegistryError::InstallFallbackFailed {
391	                        name: manifest.name.clone(),
392	                        artifact_error: Box::new(artifact_err),
393	                        source_error: Box::new(source_err),
394	                    }),
395	                }
396	            }
397	        }
398	    }
399	
400	    /// Download and install a pre-built artifact.
401	    ///
402	    /// Supports two formats:
403	    /// - **tar.gz bundle**: Contains `{name}.wasm` + `{name}.capabilities.json`
404	    /// - **bare .wasm file**: Just the WASM binary (capabilities fetched separately if available)
405	    pub async fn install_from_artifact(
406	        &self,
407	        manifest: &ExtensionManifest,
408	        force: bool,
409	    ) -> Result<InstallOutcome, RegistryError> {
410	        validate_manifest_install_inputs(manifest)?;
411	
412	        let artifact = manifest.artifacts.get("wasm32-wasip2").ok_or_else(|| {
413	            RegistryError::ExtensionNotFound(format!(
414	                "No wasm32-wasip2 artifact for '{}'",
415	                manifest.name
416	            ))
417	        })?;
418	
419	        let url = artifact.url.as_ref().ok_or_else(|| {
420	            RegistryError::ExtensionNotFound(format!(
421	                "No artifact URL for '{}'. Use --build to build from source.",
422	                manifest.name
423	            ))
424	        })?;
425	
426	        validate_artifact_url(&manifest.name, "artifacts.wasm32-wasip2.url", url)?;
427	
428	        // Require SHA256 — refuse to install unverified binaries. Check before
429	        // downloading to avoid wasting bandwidth on manifests that are missing
430	        // checksums. Uses MissingChecksum (not InvalidManifest) so that
431	        // install_with_source_fallback can fall back to building from source
432	        // when checksums haven't been populated yet (bootstrapping).
433	        let expected_sha =
434	            artifact
435	                .sha256
436	                .as_ref()
437	                .ok_or_else(|| RegistryError::MissingChecksum {
438	                    name: manifest.name.clone(),
439	                })?;
440	
441	        let target_dir = match manifest.kind {
442	            ManifestKind::Tool => &self.tools_dir,
443	            ManifestKind::Channel => &self.channels_dir,
444	            ManifestKind::McpServer => {
445	                return Err(RegistryError::InvalidManifest {
446	                    name: manifest.name.clone(),
447	                    field: "kind",
448	                    reason: "MCP servers cannot be installed as artifacts".to_string(),
449	                });
450	            }
451	        };
452	
453	        fs::create_dir_all(target_dir)
454	            .await
455	            .map_err(RegistryError::Io)?;
456	
457	        let target_wasm = target_dir.join(format!("{}.wasm", manifest.name));
458	
459	        if target_wasm.exists() && !force {
460	            return Err(RegistryError::AlreadyInstalled {
461	                name: manifest.name.clone(),
462	                path: target_wasm,
463	            });
464	        }
465	
466	        // Download
467	        println!(
468	            "Downloading {} '{}'...",
469	            manifest.kind, manifest.display_name
470	        );
471	        let bytes = download_artifact(url).await?;
472	        verify_sha256(&bytes, expected_sha, url)?;
473	
474	        let target_caps = target_dir.join(format!("{}.capabilities.json", manifest.name));
475	
476	        // Detect format and extract
477	        let has_capabilities = if is_gzip(&bytes) {
478	            // tar.gz bundle: extract {name}.wasm and {name}.capabilities.json
479	            let extracted =
480	                extract_tar_gz(&bytes, &manifest.name, &target_wasm, &target_caps, url)?;
481	            extracted.has_capabilities
482	        } else {
483	            // Bare WASM file
484	            fs::write(&target_wasm, &bytes)
485	                .await
486	                .map_err(RegistryError::Io)?;
487	
488	            // Try to get capabilities from:
489	            // 1. Separate capabilities_url in the artifact
490	            // 2. Source tree (legacy, requires repo)
491	            if let Some(ref caps_url) = artifact.capabilities_url {
492	                validate_artifact_url(
493	                    &manifest.name,
494	                    "artifacts.wasm32-wasip2.capabilities_url",
495	                    caps_url,
496	                )?;
497	                const MAX_CAPS_SIZE: usize = 1024 * 1024; // 1 MB
498	                match download_artifact(caps_url).await {
499	                    Ok(caps_bytes) if caps_bytes.len() <= MAX_CAPS_SIZE => {
500	                        fs::write(&target_caps, &caps_bytes)
501	                            .await
502	                            .map_err(RegistryError::Io)?;
503	                        true
504	                    }
505	                    Ok(caps_bytes) => {
506	                        tracing::warn!(
507	                            "Capabilities file too large ({} bytes, max {}), skipping",
508	                            caps_bytes.len(),
509	                            MAX_CAPS_SIZE
510	                        );
511	                        false
512	                    }
513	                    Err(e) => {
514	                        tracing::warn!("Failed to download capabilities from {}: {}", caps_url, e);
515	                        false
516	                    }
517	                }
518	            } else if let Some(ref source) = manifest.source {
519	                // Legacy fallback: try source tree
520	                let caps_source = self.repo_root.join(&source.dir).join(&source.capabilities);
521	                if caps_source.exists() {
522	                    fs::copy(&caps_source, &target_caps)
523	                        .await
524	                        .map_err(RegistryError::Io)?;
525	                    true
526	                } else {
527	                    false
528	                }
529	            } else {
530	                false
531	            }
532	        };
533	
534	        println!("  Installed to {}", target_wasm.display());
535	
536	        let mut warnings = Vec::new();
537	        if !has_capabilities {
538	            warnings.push(format!(
539	                "No capabilities file found for '{}'. Auth and hooks may not work.",
540	                manifest.name
541	            ));
542	        }
543	
544	        Ok(InstallOutcome {
545	            name: manifest.name.clone(),
546	            kind: manifest.kind,
547	            wasm_path: target_wasm,
548	            has_capabilities,
549	            warnings,
550	        })
551	    }
