687	/// Result of extracting a tar.gz bundle.
688	#[derive(Debug)]
689	struct ExtractResult {
690	    has_capabilities: bool,
691	}
692	
693	/// Extract a tar.gz archive, looking for `{name}.wasm` and `{name}.capabilities.json`.
694	fn extract_tar_gz(
695	    bytes: &[u8],
696	    name: &str,
697	    target_wasm: &Path,
698	    target_caps: &Path,
699	    url: &str,
700	) -> Result<ExtractResult, RegistryError> {
701	    use flate2::read::GzDecoder;
702	    use tar::Archive;
703	
704	    use std::io::Read as _;
705	
706	    let decoder = GzDecoder::new(bytes);
707	    let mut archive = Archive::new(decoder);
708	    // Defense-in-depth: do not preserve permissions or extended attributes
709	    archive.set_preserve_permissions(false);
710	    #[cfg(any(unix, target_os = "redox"))]
711	    archive.set_unpack_xattrs(false);
712	
713	    // 100 MB cap on decompressed entry size to prevent decompression bombs
714	    const MAX_ENTRY_SIZE: u64 = 100 * 1024 * 1024;
715	
716	    let wasm_filename = format!("{}.wasm", name);
717	    let caps_filename = format!("{}.capabilities.json", name);
718	    let mut found_wasm = false;
719	    let mut found_caps = false;
720	
721	    let entries = archive
722	        .entries()
723	        .map_err(|e| RegistryError::DownloadFailed {
724	            url: url.to_string(),
725	            reason: format!("failed to read tar.gz entries: {}", e),
726	        })?;
727	
728	    for entry in entries {
729	        let mut entry = entry.map_err(|e| RegistryError::DownloadFailed {
730	            url: url.to_string(),
731	            reason: format!("failed to read tar.gz entry: {}", e),
732	        })?;
733	
734	        if entry.size() > MAX_ENTRY_SIZE {
735	            return Err(RegistryError::DownloadFailed {
736	                url: url.to_string(),
737	                reason: format!(
738	                    "archive entry too large ({} bytes, max {} bytes)",
739	                    entry.size(),
740	                    MAX_ENTRY_SIZE
741	                ),
742	            });
743	        }
744	
745	        let entry_path = entry
746	            .path()
747	            .map_err(|e| RegistryError::DownloadFailed {
748	                url: url.to_string(),
749	                reason: format!("invalid path in tar.gz: {}", e),
750	            })?
751	            .to_path_buf();
752	
753	        // Match by filename (ignoring any directory prefix in the archive)
754	        let filename = entry_path
755	            .file_name()
756	            .and_then(|n| n.to_str())
757	            .unwrap_or("");
758	
759	        if filename == wasm_filename {
760	            let mut data = Vec::with_capacity(entry.size() as usize);
761	            std::io::Read::read_to_end(&mut entry.by_ref().take(MAX_ENTRY_SIZE), &mut data)
762	                .map_err(|e| RegistryError::DownloadFailed {
763	                    url: url.to_string(),
764	                    reason: format!("failed to read {} from archive: {}", wasm_filename, e),
765	                })?;
766	            std::fs::write(target_wasm, &data).map_err(RegistryError::Io)?;
767	            found_wasm = true;
768	        } else if filename == caps_filename {
769	            let mut data = Vec::with_capacity(entry.size() as usize);
770	            std::io::Read::read_to_end(&mut entry.by_ref().take(MAX_ENTRY_SIZE), &mut data)
771	                .map_err(|e| RegistryError::DownloadFailed {
772	                    url: url.to_string(),
773	                    reason: format!("failed to read {} from archive: {}", caps_filename, e),
774	                })?;
775	            std::fs::write(target_caps, &data).map_err(RegistryError::Io)?;
776	            found_caps = true;
777	        }
778	    }
779	
780	    if !found_wasm {
781	        return Err(RegistryError::DownloadFailed {
782	            url: url.to_string(),
783	            reason: format!(
784	                "tar.gz archive does not contain '{}'. Archive may be malformed.",
785	                wasm_filename
786	            ),
787	        });
788	    }
789	
790	    Ok(ExtractResult {
791	        has_capabilities: found_caps,
792	    })
793	}
