267	    /// Get all manifests.
268	    pub fn all(&self) -> Vec<&ExtensionManifest> {
269	        let mut items: Vec<_> = self.manifests.values().collect();
270	        items.sort_by(|a, b| a.name.cmp(&b.name));
271	        items
272	    }
273	
274	    /// List manifests, optionally filtered by kind and/or tag.
275	    pub fn list(&self, kind: Option<ManifestKind>, tag: Option<&str>) -> Vec<&ExtensionManifest> {
276	        let mut results: Vec<_> = self
277	            .manifests
278	            .values()
279	            .filter(|m| kind.is_none_or(|k| m.kind == k))
280	            .filter(|m| tag.is_none_or(|t| m.tags.iter().any(|mt| mt == t)))
281	            .collect();
282	        results.sort_by(|a, b| a.name.cmp(&b.name));
283	        results
284	    }
