286	    /// Get a manifest by name. Tries exact key match first ("tools/github"),
287	    /// then searches by bare name ("github").
288	    ///
289	    /// If a bare name matches more than one prefix, returns `None`.
290	    /// Use a qualified key ("tools/github", "channels/telegram", or
291	    /// "mcp-servers/notion") to disambiguate.
292	    pub fn get(&self, name: &str) -> Option<&ExtensionManifest> {
293	        // Try exact key first
294	        if let Some(m) = self.manifests.get(name) {
295	            return Some(m);
296	        }
297	
298	        // Try with kind prefix, detecting collisions
299	        let candidates: Vec<_> = ["tools", "channels", "mcp-servers"]
300	            .iter()
301	            .filter_map(|prefix| self.manifests.get(&format!("{}/{}", prefix, name)))
302	            .collect();
303	
304	        if candidates.len() == 1 {
305	            Some(candidates[0])
306	        } else {
307	            None // ambiguous or not found
308	        }
309	    }
310	
311	    /// Get a manifest by name, returning a `Result` with an explicit error for
312	    /// ambiguous bare names.
313	    pub fn get_strict(&self, name: &str) -> Result<&ExtensionManifest, RegistryError> {
314	        // Try exact key first
315	        if let Some(m) = self.manifests.get(name) {
316	            return Ok(m);
317	        }
318	
319	        let prefixes: &[(&str, &str)] = &[
320	            ("tools", "tool"),
321	            ("channels", "channel"),
322	            ("mcp-servers", "mcp_server"),
323	        ];
324	
325	        let matches: Vec<_> = prefixes
326	            .iter()
327	            .filter(|(prefix, _)| self.manifests.contains_key(&format!("{}/{}", prefix, name)))
328	            .collect();
329	
330	        match matches.len() {
331	            0 => Err(RegistryError::ExtensionNotFound(name.to_string())),
332	            1 => {
333	                let (prefix, _) = matches[0];
334	                let key = format!("{}/{}", prefix, name);
335	                self.manifests
336	                    .get(&key)
337	                    .ok_or_else(|| RegistryError::ExtensionNotFound(name.to_string()))
338	            }
339	            _ => {
340	                let (prefix_a, kind_a) = matches[0];
341	                let (prefix_b, kind_b) = matches[1];
342	                Err(RegistryError::AmbiguousName {
343	                    name: name.to_string(),
344	                    kind_a,
345	                    prefix_a,
346	                    kind_b,
347	                    prefix_b,
348	                })
349	            }
350	        }
351	    }
352	
353	    /// Get the full key ("tools/github", "channels/telegram", or
354	    /// "mcp-servers/notion") for a manifest.
355	    pub fn key_for(&self, name: &str) -> Option<String> {
356	        if self.manifests.contains_key(name) {
357	            return Some(name.to_string());
358	        }
359	
360	        let matches: Vec<String> = ["tools", "channels", "mcp-servers"]
361	            .iter()
362	            .filter_map(|prefix| {
363	                let key = format!("{}/{}", prefix, name);
364	                if self.manifests.contains_key(&key) {
365	                    Some(key)
366	                } else {
367	                    None
368	                }
369	            })
370	            .collect();
371	
372	        if matches.len() == 1 {
373	            matches.into_iter().next()
374	        } else {
375	            None // ambiguous or not found
376	        }
377	    }
378	
379	    /// Search manifests by query string (matches name, display_name, description, keywords).
380	    pub fn search(&self, query: &str) -> Vec<&ExtensionManifest> {
381	        let query_lower = query.to_lowercase();
382	        let tokens: Vec<&str> = query_lower.split_whitespace().collect();
383	
384	        let mut scored: Vec<(&ExtensionManifest, usize)> = self
385	            .manifests
386	            .values()
387	            .filter_map(|m| {
388	                let score = Self::score_manifest(m, &tokens);
389	                if score > 0 { Some((m, score)) } else { None }
390	            })
391	            .collect();
392	
393	        scored.sort_by(|a, b| b.1.cmp(&a.1).then(a.0.name.cmp(&b.0.name)));
394	        scored.into_iter().map(|(m, _)| m).collect()
395	    }
396	
397	    fn score_manifest(manifest: &ExtensionManifest, tokens: &[&str]) -> usize {
398	        let mut score = 0;
399	        let name_lower = manifest.name.to_lowercase();
400	        let display_lower = manifest.display_name.to_lowercase();
401	        let desc_lower = manifest.description.to_lowercase();
402	
403	        for token in tokens {
404	            if name_lower == *token {
405	                score += 10;
406	            } else if name_lower.contains(token) {
407	                score += 5;
408	            }
409	
410	            if display_lower == *token {
411	                score += 8;
412	            } else if display_lower.contains(token) {
413	                score += 4;
414	            }
415	
416	            if desc_lower.contains(token) {
417	                score += 2;
418	            }
419	
420	            for kw in &manifest.keywords {
421	                if kw.to_lowercase() == *token {
422	                    score += 6;
423	                } else if kw.to_lowercase().contains(token) {
424	                    score += 3;
425	                }
426	            }
427	
428	            for tag in &manifest.tags {
429	                if tag.to_lowercase() == *token {
430	                    score += 4;
431	                }
432	            }
433	        }
434	
435	        score
436	    }
