438	    /// Get a bundle definition by name.
439	    pub fn get_bundle(&self, name: &str) -> Option<&BundleDefinition> {
440	        self.bundles.get(name)
441	    }
442	
443	    /// List all bundle names.
444	    pub fn bundle_names(&self) -> Vec<&str> {
445	        let mut names: Vec<_> = self.bundles.keys().map(|s| s.as_str()).collect();
446	        names.sort();
447	        names
448	    }
449	
450	    /// Resolve a bundle into its constituent manifests.
451	    /// Returns the manifests and any extension keys that couldn't be found.
452	    pub fn resolve_bundle(
453	        &self,
454	        bundle_name: &str,
455	    ) -> Result<(Vec<&ExtensionManifest>, Vec<String>), RegistryError> {
456	        let bundle = self
457	            .bundles
458	            .get(bundle_name)
459	            .ok_or_else(|| RegistryError::BundleNotFound(bundle_name.to_string()))?;
460	
461	        let mut found = Vec::new();
462	        let mut missing = Vec::new();
463	
464	        for ext_key in &bundle.extensions {
465	            if let Some(manifest) = self.manifests.get(ext_key) {
466	                found.push(manifest);
467	            } else {
468	                missing.push(ext_key.clone());
469	            }
470	        }
471	
472	        Ok((found, missing))
473	    }
474	
475	    /// Check if a name refers to a bundle rather than an individual extension.
476	    pub fn is_bundle(&self, name: &str) -> bool {
477	        self.bundles.contains_key(name)
478	    }
479	
480	    /// Resolve a name to either a single manifest or the manifests in a bundle.
481	    /// Returns (manifests, bundle_definition_if_bundle).
482	    pub fn resolve(
483	        &self,
484	        name: &str,
485	    ) -> Result<(Vec<&ExtensionManifest>, Option<&BundleDefinition>), RegistryError> {
486	        // Check bundle first
487	        if let Some(bundle) = self.bundles.get(name) {
488	            let (manifests, missing) = self.resolve_bundle(name)?;
489	            if !missing.is_empty() {
490	                tracing::warn!(
491	                    "Bundle '{}' references missing extensions: {:?}",
492	                    name,
493	                    missing
494	                );
495	            }
496	            return Ok((manifests, Some(bundle)));
497	        }
498	
499	        // Single extension (use get_strict to catch ambiguous bare names)
500	        let manifest = self.get_strict(name)?;
501	        Ok((vec![manifest], None))
502	    }
503	}
