3811	/// Discover which tools are already installed in the tools directory.
3812	///
3813	/// Returns a set of tool names (the stem of .wasm files).
3814	async fn discover_installed_tools(tools_dir: &std::path::Path) -> HashSet<String> {
3815	    let mut names = HashSet::new();
3816	
3817	    if !tools_dir.is_dir() {
3818	        return names;
3819	    }
3820	
3821	    let mut entries = match tokio::fs::read_dir(tools_dir).await {
3822	        Ok(e) => e,
3823	        Err(_) => return names,
3824	    };
3825	
3826	    while let Ok(Some(entry)) = entries.next_entry().await {
3827	        let path = entry.path();
3828	        if path.extension().and_then(|e| e.to_str()) == Some("wasm")
3829	            && let Some(stem) = path.file_stem().and_then(|s| s.to_str())
3830	        {
3831	            names.insert(stem.to_string());
3832	        }
3833	    }
3834	
3835	    names
3836	}
