3842	) -> Result<Option<Vec<String>>, SetupError> {
3843	    let bundled: HashSet<&str> = available_channel_names().iter().copied().collect();
3844	    let selected_missing: HashSet<String> = selected_channels
3845	        .iter()
3846	        .filter(|name| bundled.contains(name.as_str()) && !already_installed.contains(*name))
3847	        .cloned()
3848	        .collect();
3849	
3850	    if selected_missing.is_empty() {
3851	        return Ok(None);
3852	    }
3853	
