86	fn validate_manifest_install_inputs(manifest: &ExtensionManifest) -> Result<(), RegistryError> {
87	    let is_valid_name = !manifest.name.is_empty()
88	        && manifest
89	            .name
90	            .chars()
91	            .all(|c| c.is_ascii_lowercase() || c.is_ascii_digit() || c == '-' || c == '_');
92	
93	    if !is_valid_name {
94	        return Err(RegistryError::InvalidManifest {
95	            name: manifest.name.clone(),
96	            field: "name",
97	            reason: "name must contain only lowercase letters, digits, '-' or '_'".to_string(),
98	        });
99	    }
100	
101	    // MCP servers are not installed via this path
102	    if manifest.kind == ManifestKind::McpServer {
103	        return Ok(());
104	    }
105	
106	    let source = match &manifest.source {
107	        Some(s) => s,
108	        None => {
109	            return Err(RegistryError::InvalidManifest {
110	                name: manifest.name.clone(),
111	                field: "source",
112	                reason: "WASM extensions must have a source spec".to_string(),
113	            });
114	        }
115	    };
116	
117	    let expected_prefix = match manifest.kind {
118	        ManifestKind::Tool => "tools-src/",
119	        ManifestKind::Channel => "channels-src/",
120	        ManifestKind::McpServer => unreachable!(),
121	    };
122	
123	    if !source.dir.starts_with(expected_prefix) {
124	        return Err(RegistryError::InvalidManifest {
125	            name: manifest.name.clone(),
126	            field: "source.dir",
127	            reason: format!("must start with '{}'", expected_prefix),
128	        });
129	    }
130	
131	    let source_path = Path::new(&source.dir);
132	    let has_unsafe_component = source_path.components().any(|component| {
133	        matches!(
134	            component,
135	            Component::ParentDir | Component::RootDir | Component::Prefix(_) | Component::CurDir
136	        )
137	    });
138	
139	    if source_path.is_absolute() || has_unsafe_component {
140	        return Err(RegistryError::InvalidManifest {
141	            name: manifest.name.clone(),
142	            field: "source.dir",
143	            reason: "must be a safe relative path without traversal segments".to_string(),
144	        });
145	    }
146	
147	    let has_path_separator = source.capabilities.contains('/')
148	        || source.capabilities.contains('\\')
149	        || source.capabilities.contains("..");
150	
151	    if has_path_separator {
152	        return Err(RegistryError::InvalidManifest {
153	            name: manifest.name.clone(),
154	            field: "source.capabilities",
155	            reason: "must be a file name without path separators".to_string(),
156	        });
157	    }
158	
159	    Ok(())
160	}

