1	//! JSON schema for WASM channel capabilities files.
2	//!
3	//! External WASM channels declare their required capabilities via a sidecar JSON file
4	//! (e.g., `slack.capabilities.json`). This module defines the schema for those files
5	//! and provides conversion to runtime [`ChannelCapabilities`].
6	//!
7	//! # Example Capabilities File
8	//!
9	//! ```json
10	//! {
11	//!   "type": "channel",
12	//!   "name": "slack",
13	//!   "description": "Slack Events API channel",
14	//!   "capabilities": {
15	//!     "http": {
16	//!       "allowlist": [
17	//!         { "host": "slack.com", "path_prefix": "/api/" }
18	//!       ],
19	//!       "credentials": {
20	//!         "slack_bot": {
21	//!           "secret_name": "slack_bot_token",
22	//!           "location": { "type": "bearer" },
23	//!           "host_patterns": ["slack.com"]
24	//!         }
25	//!       }
26	//!     },
27	//!     "secrets": { "allowed_names": ["slack_*"] },
28	//!     "channel": {
29	//!       "allowed_paths": ["/webhook/slack"],
30	//!       "allow_polling": false,
31	//!       "workspace_prefix": "channels/slack/",
32	//!       "emit_rate_limit": { "messages_per_minute": 100 }
33	//!     }
34	//!   },
35	//!   "config": {
36	//!     "signing_secret_name": "slack_signing_secret"
37	//!   }
38	//! }
39	//! ```
