53	/// Root schema for a channel capabilities JSON file.
54	#[derive(Debug, Clone, Default, Serialize, Deserialize)]
55	pub struct ChannelCapabilitiesFile {
56	    /// Extension version (semver).
57	    #[serde(default)]
58	    pub version: Option<String>,
59	
60	    /// WIT interface version this channel was compiled against (semver).
61	    #[serde(default)]
62	    pub wit_version: Option<String>,
63	
64	    /// File type, must be "channel".
65	    #[serde(default = "default_type")]
66	    pub r#type: String,
67	
68	    /// Channel name.
69	    pub name: String,
70	
71	    /// Channel description.
72	    #[serde(default)]
73	    pub description: Option<String>,
74	
75	    /// Setup configuration for the wizard.
76	    #[serde(default)]
77	    pub setup: SetupSchema,
78	
79	    /// Capabilities (tool + channel specific).
80	    #[serde(default)]
81	    pub capabilities: ChannelCapabilitiesSchema,
82	
83	    /// Channel-specific configuration passed to on_start.
84	    #[serde(default)]
85	    pub config: HashMap<String, serde_json::Value>,
86	}
87	
88	fn default_type() -> String {
89	    "channel".to_string()
90	}
