92	impl ChannelCapabilitiesFile {
93	    /// Parse from JSON string.
94	    pub fn from_json(json: &str) -> Result<Self, serde_json::Error> {
95	        serde_json::from_str(json)
96	    }
97	
98	    /// Parse from JSON bytes.
99	    pub fn from_bytes(bytes: &[u8]) -> Result<Self, serde_json::Error> {
100	        serde_json::from_slice(bytes)
101	    }
102	
103	    /// Validate the capabilities file and emit warnings for common misconfigurations.
104	    ///
105	    /// Called once at load time to catch issues early. Warnings are emitted via
106	    /// `tracing::warn` so they show up in startup logs without blocking loading.
107	    pub fn validate(&self) {
108	        const MIN_PROMPT_LENGTH: usize = 30;
109	
110	        // Check for short prompts in required_secrets
111	        for secret in &self.setup.required_secrets {
112	            if secret.prompt.len() < MIN_PROMPT_LENGTH {
113	                tracing::warn!(
114	                    channel = self.name,
115	                    secret = secret.name,
116	                    prompt = secret.prompt,
117	                    "setup.required_secrets prompt is shorter than {} chars — \
118	                     consider a more descriptive prompt that tells the user where to find this value",
119	                    MIN_PROMPT_LENGTH
120	                );
121	            }
122	        }
123	
124	        // Has required_secrets but no setup_url
125	        if (!self.setup.required_secrets.is_empty() || !self.setup.required_fields.is_empty())
126	            && self.setup.setup_url.is_none()
127	        {
128	            tracing::warn!(
129	                channel = self.name,
130	                "setup requirements defined but no setup.setup_url — \
131	                 user has no link to obtain credentials"
132	            );
133	        }
134	    }
135	
136	    /// Convert to runtime ChannelCapabilities.
137	    pub fn to_capabilities(&self) -> ChannelCapabilities {
138	        self.capabilities.to_channel_capabilities(&self.name)
139	    }
140	
141	    /// Get the channel config as JSON string.
142	    pub fn config_json(&self) -> String {
143	        serde_json::to_string(&self.config).unwrap_or_else(|_| "{}".to_string())
144	    }
145	
146	    /// Get the webhook secret header name for this channel.
147	    ///
148	    /// Returns the configured header name from capabilities, or a sensible default.
149	    pub fn webhook_secret_header(&self) -> Option<&str> {
150	        self.capabilities
151	            .channel
152	            .as_ref()
153	            .and_then(|c| c.webhook.as_ref())
154	            .and_then(|w| w.secret_header.as_deref())
155	    }
156	
157	    /// Get the signature verification key secret name for this channel.
158	    ///
159	    /// Returns the secret name declared in `webhook.signature_key_secret_name`,
160	    /// used to look up the Ed25519 public key in the secrets store.
161	    pub fn signature_key_secret_name(&self) -> Option<&str> {
162	        self.capabilities
163	            .channel
164	            .as_ref()
165	            .and_then(|c| c.webhook.as_ref())
166	            .and_then(|w| w.signature_key_secret_name.as_deref())
167	    }
168	
169	    /// Get the HMAC-SHA256 signing secret name for this channel.
170	    ///
171	    /// Returns the secret name declared in `webhook.hmac_secret_name`,
172	    /// used to look up the HMAC signing secret in the secrets store (Slack-style).
173	    pub fn hmac_secret_name(&self) -> Option<&str> {
174	        self.capabilities
175	            .channel
176	            .as_ref()
177	            .and_then(|c| c.webhook.as_ref())
178	            .and_then(|w| w.hmac_secret_name.as_deref())
179	    }
180	
181	    /// Get the webhook secret name for this channel.
182	    ///
183	    /// Returns the configured secret name or defaults to "{channel_name}_webhook_secret".
184	    pub fn webhook_secret_name(&self) -> String {
185	        self.capabilities
186	            .channel
187	            .as_ref()
188	            .and_then(|c| c.webhook.as_ref())
189	            .and_then(|w| w.secret_name.clone())
190	            .unwrap_or_else(|| format!("{}_webhook_secret", self.name))
191	    }
192	}
