194	/// Schema for channel capabilities.
195	#[derive(Debug, Clone, Default, Serialize, Deserialize)]
196	pub struct ChannelCapabilitiesSchema {
197	    /// Tool capabilities (HTTP, secrets, workspace_read).
198	    /// Note: Using the struct directly (not Option) because #[serde(flatten)]
199	    /// with Option<T> doesn't work correctly when T has all-optional fields.
200	    #[serde(flatten)]
201	    pub tool: ToolCapabilitiesFile,
202	
203	    /// Channel-specific capabilities.
204	    #[serde(default)]
205	    pub channel: Option<ChannelSpecificCapabilitiesSchema>,
206	}
207	
208	impl ChannelCapabilitiesSchema {
209	    /// Convert to runtime ChannelCapabilities.
210	    pub fn to_channel_capabilities(&self, channel_name: &str) -> ChannelCapabilities {
211	        let tool_caps = self.tool.to_capabilities();
212	
213	        let mut caps =
214	            ChannelCapabilities::for_channel(channel_name).with_tool_capabilities(tool_caps);
215	
216	        if let Some(channel) = &self.channel {
217	            caps.allowed_paths = channel.allowed_paths.clone();
218	            caps.allow_polling = channel.allow_polling;
219	            caps.min_poll_interval_ms = channel
220	                .min_poll_interval_ms
221	                .unwrap_or(MIN_POLL_INTERVAL_MS)
222	                .max(MIN_POLL_INTERVAL_MS);
223	
224	            if let Some(prefix) = &channel.workspace_prefix {
225	                caps.workspace_prefix = prefix.clone();
226	            }
227	
228	            if let Some(rate) = &channel.emit_rate_limit {
229	                caps.emit_rate_limit = rate.to_emit_rate_limit();
230	            }
231	
232	            if let Some(max_size) = channel.max_message_size {
233	                caps.max_message_size = max_size;
234	            }
235	
236	            if let Some(timeout_secs) = channel.callback_timeout_secs {
237	                caps.callback_timeout = Duration::from_secs(timeout_secs);
238	            }
239	        }
240	
241	        caps
242	    }
243	}
